    11→class Lexer {
    12→  private source: string;
    13→  private position: number = 0;
    14→
    15→  constructor(source: string) {
    16→    this.source = source;
    17→  }
    18→
    19→  tokenize(): Token[] {
    20→    const tokens: Token[] = [];
    21→
    22→    while (this.position < this.source.length) {
    23→      this.skipWhitespace();
    24→
    25→      if (this.position >= this.source.length) break;
    26→
    27→      const ch = this.source[this.position];
    28→
    29→      // 숫자
    30→      if (this.isDigit(ch)) {
    31→        tokens.push(this.readNumber());
    32→      }
    33→      // 식별자/키워드
    34→      else if (this.isLetter(ch)) {
    35→        tokens.push(this.readIdentifier());
    36→      }
