      expect(ast.designBlocks[0].name).toBeUndefined();
    });

    test('parses mixed functions and design blocks', () => {
      const source = `
        fn greet input string output string intent "greeting"

        @animation slideIn {
          duration: 500;
        }

        fn farewell input string output string
      `;
      const parser = new Parser(lex(source));
      const ast = parser.parse();

      expect(ast.statements).toHaveLength(2); // 2 functions
      expect(ast.designBlocks).toHaveLength(1); // 1 design block
    });

    test('parses all 5 design engines', () => {
      const engines = ['animation', 'glass', 'transform3d', 'micro', 'scroll'];
      engines.forEach(engine => {
        const source = `@${engine === 'transform3d' ? '3d' : engine} { }`;
        const parser = new Parser(lex(source));
        const ast = parser.parse();

        expect(ast.designBlocks).toHaveLength(1);
        expect(ast.designBlocks[0].engine).toBe(engine);
      });
    });

    test('handles nested braces in design block content', () => {
      const source = `
        @micro {
          trigger: hover;
          action: { scale: 1.1; opacity: 1; }
        }
      `;
      const parser = new Parser(lex(source));
      const ast = parser.parse();

      expect(ast.designBlocks).toHaveLength(1);
      // Verify nested content parsed correctly
    });
  });

  // Integration tests
  describe('DesignIntegration - Compilation', () => {
    test('compiles design blocks to CSS and JS', () => {
      const blocks: DesignBlockDeclaration[] = [
        {
          type: 'design-block',
          engine: 'animation',
          name: 'fadeIn',
          properties: new Map([
            ['duration', '300'],
            ['opacity', '0 → 1']
          ])
        }
      ];

      const integration = new DesignIntegration();
      const result = integration.compileDesignBlocks(blocks);

      expect(result.css).toContain('@keyframes fadeIn');
      expect(result.javascript).toBeDefined();
      expect(result.ast).toEqual(blocks);
    });

    test('compiles multiple design blocks', () => {
      const blocks = [
        createAnimationBlock('spin'),
        createGlassBlock(),
        createMicroBlock('hover'),
        createScrollBlock('fade')
      ];

      const integration = new DesignIntegration();
      const result = integration.compileDesignBlocks(blocks);

      expect(result.css).toContain('@keyframes spin');
      expect(result.css).toContain('backdrop-filter');
      expect(result.javascript).toContain('hover');
      expect(result.javascript).toContain('scroll');
    });
  });

  // E2E tests
  describe('End-to-End - Full Pipeline', () => {
    test('compiles HeroCard.free to CSS and JS', () => {
      const content = fs.readFileSync('./examples/HeroCard.free', 'utf-8');
      const lexer = new Lexer(content);
      const parser = new Parser(new TokenBuffer(lexer));
      const ast = parser.parse();

      expect(ast.designBlocks.length).toBeGreaterThan(0);

      const integration = new DesignIntegration();
      const result = integration.compileDesignBlocks(ast.designBlocks);

      expect(result.css.length).toBeGreaterThan(100);
      expect(result.javascript.length).toBeGreaterThan(100);
    });

    test('preserves both functions and design blocks in same file', () => {
      const source = `
        fn transform input string output string intent "transform"

        @animation shine {
          duration: 1000;
          background: linear-gradient(45deg, transparent, rgba(255,255,255,0.2), transparent);
        }

        fn validate input string output bool
      `;

      const lexer = new Lexer(source);
      const parser = new Parser(new TokenBuffer(lexer));
      const ast = parser.parse();

      // Both present
      expect(ast.statements.length).toBe(2);
      expect(ast.designBlocks.length).toBe(1);

      // Can compile separately
      const integration = new DesignIntegration();
      const designResult = integration.compileDesignBlocks(ast.designBlocks);

      expect(designResult.css).toContain('shine');
    });
  });
});
